python3 -c "
import json
with open('/app/resources/treasury_bulletin_2007_09.json', 'r') as f:
    data = json.load(f)

# Search for Payroll Employment in the JSON
def search_json(obj, path=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if 'payroll' in key.lower() or 'employment' in key.lower():
                print(f'Found: {path}/{key}')
            search_json(value, f'{path}/{key}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_json(item, f'{path}[{i}]')

search_json(data)
"

